<style>
    .member-theme-dark .learning-shell{--surface:var(--theme-dark-surface-color);--surface-muted:color-mix(in srgb,var(--theme-dark-surface-color) 82%,var(--theme-dark-canvas-color));--ink:var(--theme-dark-ink);--muted:var(--theme-dark-muted);--line:var(--theme-dark-line);--line-strong:color-mix(in srgb,var(--theme-dark-ink) 28%,var(--theme-dark-surface-color))}
    .learning-shell{display:grid;gap:18px}.learning-filter{display:grid;grid-template-columns:minmax(180px,1fr) repeat(2,minmax(130px,.45fr)) auto;gap:8px;margin:0 0 16px}.learning-filter input,.learning-filter select{min-width:0;min-height:40px;border:1px solid var(--line-strong);border-radius:10px;padding:0 11px;background:var(--surface);color:var(--ink);font:inherit;font-size:.7rem}.learning-hero{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(240px,.75fr);gap:24px;overflow:hidden;border:1px solid var(--line-strong);border-radius:23px;padding:28px;background:linear-gradient(135deg,color-mix(in srgb,var(--brand) 15%,var(--surface)),var(--surface));box-shadow:0 15px 42px rgb(20 47 30 / 7%)}.learning-kicker{margin:0 0 9px;color:var(--brand);font-size:.6rem;font-weight:850;letter-spacing:.15em;text-transform:uppercase}.learning-hero h1{max-width:700px;margin:0;color:var(--ink);font-size:clamp(1.65rem,3vw,2.7rem);line-height:1.03;letter-spacing:-.055em}.learning-hero p{max-width:680px;margin:13px 0 0;color:var(--muted);font-size:.8rem;line-height:1.65}.learning-hero-visual{display:grid;place-items:center;border:1px solid color-mix(in srgb,var(--brand) 20%,var(--line));border-radius:18px;background:linear-gradient(145deg,color-mix(in srgb,var(--brand) 90%,#153423),color-mix(in srgb,var(--accent) 38%,var(--brand)));color:#fff}.learning-hero-visual .ui-icon{width:62px;height:62px}.learning-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.learning-card,.learning-panel,.learning-module,.learning-assessment,.learning-class{border:1px solid var(--line-strong);background:var(--surface);box-shadow:0 10px 30px rgb(18 42 27 / 5%)}.learning-card{display:grid;overflow:hidden;border-radius:18px}.learning-card-cover{display:flex;min-height:120px;align-items:flex-end;padding:18px;background:linear-gradient(145deg,color-mix(in srgb,var(--brand) 86%,#173424),color-mix(in srgb,var(--accent) 42%,var(--brand)));color:#fff}.learning-card-cover span{font-size:.6rem;font-weight:830;letter-spacing:.12em;text-transform:uppercase}.learning-card-body{display:grid;gap:11px;padding:18px}.learning-card h2{margin:0;color:var(--ink);font-size:1rem;line-height:1.25}.learning-card p{margin:0;color:var(--muted);font-size:.69rem;line-height:1.55}.learning-meta{display:flex;flex-wrap:wrap;gap:7px}.learning-pill{display:inline-flex;align-items:center;border:1px solid var(--line);border-radius:999px;padding:5px 9px;background:var(--surface-muted);color:var(--muted);font-size:.57rem;font-weight:760}.learning-button{display:inline-flex;min-height:40px;align-items:center;justify-content:center;gap:7px;border:1px solid color-mix(in srgb,var(--brand) 65%,#173524);border-radius:11px;padding:0 14px;background:var(--brand);color:#fff!important;font-size:.68rem;font-weight:800;text-decoration:none;cursor:pointer}.learning-button.is-quiet{border-color:var(--line-strong);background:var(--surface);color:var(--ink)!important}.learning-progress{height:7px;overflow:hidden;border-radius:999px;background:var(--surface-muted)}.learning-progress span{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,var(--brand),var(--accent))}.learning-panel{padding:21px;border-radius:19px}.learning-panel>header{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;margin-bottom:16px}.learning-panel h2,.learning-panel h3{margin:0;color:var(--ink);letter-spacing:-.03em}.learning-panel header p{margin:6px 0 0;color:var(--muted);font-size:.7rem;line-height:1.5}.learning-stack{display:grid;gap:12px}.learning-module,.learning-assessment,.learning-class{border-radius:16px;padding:17px}.learning-module>header,.learning-assessment>header,.learning-class>header{display:flex;justify-content:space-between;gap:12px}.learning-module h3,.learning-assessment h3,.learning-class h3{margin:0;color:var(--ink);font-size:.88rem}.learning-lessons{display:grid;gap:8px;margin-top:13px}.learning-lesson{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:11px;border:1px solid var(--line);border-radius:12px;padding:11px;background:var(--surface-muted)}.learning-lesson-index{display:grid;width:29px;height:29px;place-items:center;border-radius:9px;background:color-mix(in srgb,var(--brand) 12%,var(--surface));color:var(--brand);font-size:.6rem;font-weight:850}.learning-lesson strong{display:block;color:var(--ink);font-size:.7rem}.learning-lesson small{color:var(--muted);font-size:.58rem}.learning-content{margin-top:9px;color:var(--ink);font-size:.72rem;line-height:1.65;white-space:pre-line}.learning-media{overflow:hidden;margin-top:12px;border:1px solid var(--line);border-radius:12px}.learning-media iframe,.learning-media video,.learning-media audio{display:block;width:100%;min-height:260px;border:0}.learning-assessment form{display:grid;gap:13px;margin-top:14px}.learning-question{display:grid;gap:8px}.learning-question>strong{color:var(--ink);font-size:.72rem}.learning-option{display:flex;align-items:center;gap:9px;border:1px solid var(--line);border-radius:10px;padding:9px 11px;color:var(--muted);font-size:.67rem}.learning-certificate{display:flex;align-items:center;justify-content:space-between;gap:18px;border:1px solid color-mix(in srgb,var(--accent) 45%,var(--line));border-radius:18px;padding:20px;background:linear-gradient(135deg,color-mix(in srgb,var(--accent) 10%,var(--surface)),var(--surface))}.learning-empty{padding:28px;border:1px dashed var(--line-strong);border-radius:15px;text-align:center;color:var(--muted);font-size:.7rem}.member-theme-dark :is(.learning-hero,.learning-card,.learning-panel,.learning-module,.learning-assessment,.learning-class){box-shadow:none}
    @media(max-width:900px){.learning-hero{grid-template-columns:1fr}.learning-hero-visual{min-height:150px}.learning-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:620px){.learning-filter{grid-template-columns:1fr 1fr}.learning-filter input{grid-column:1/-1}.learning-hero{padding:21px;border-radius:18px}.learning-hero h1{font-size:1.65rem}.learning-grid{grid-template-columns:1fr}.learning-panel{padding:16px}.learning-panel>header,.learning-certificate{display:grid}.learning-media iframe,.learning-media video{min-height:190px}}
    .member-theme-dark .learning-shell{--surface:var(--theme-dark-surface-color);--surface-muted:color-mix(in srgb,var(--theme-dark-surface-color) 82%,var(--theme-dark-canvas-color));--ink:var(--theme-dark-surface-ink);--muted:var(--theme-muted);--line:var(--theme-line);--line-strong:color-mix(in srgb,var(--theme-dark-surface-ink) 28%,var(--theme-dark-surface-color))}
</style>
